-- DMF0020 button 정의 (2026-06-12 SHT_NM exchange/priceBatch 정렬)
MERGE INTO SCM_ADM_MNU_BTN_MPG_M t USING (SELECT 'DMF0020' MNU_ID, 'exchange' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL) s
   ON (t.MNU_ID=s.MNU_ID AND t.SHT_NM=s.SHT_NM AND t.MNU_BTN_CD=s.MNU_BTN_CD)
 WHEN MATCHED THEN UPDATE SET API_ID='DMF0020_exchange_SAVE', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (MNU_ID, SHT_NM, MNU_BTN_CD, API_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('DMF0020','exchange','SAVE','DMF0020_exchange_SAVE','Y','admin',SYSDATE,'admin',SYSDATE);
